/bin/bash -lc "cat > src/util/ordersApi.mjs <<'EOF'
// Normalizes the backend order-list response into the stable shape the
// storefront consumes.
//
// "'`RecentOrder.js` loads the list from GET {base}/auth/orders (APP_API_VERSION
// is /api/v1/), which the backend serves as a ReadableOrderList extending
// ReadableList. Those classes define the fields read below:
//   - orders        (List<ReadableOrder>) -> list of orders
//   - pageCount     (int)                 -> number of pages
//   - totalRecords  (long)                -> total number of records
//   - itemsOnPage   (int)                 -> number of records on this page

function toArray(value) {
  return Array.isArray(value) ? value : [];
}

function toCount(value) {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

export function normalizeOrderList(response) {
  const source = response && typeof response === "object" ? response : {};
  return {
    orders: toArray(source.orders),
    pages: toCount(source.pageCount),
    total: toCount(source.totalRecords),
    onThisPage: toCount(source.itemsOnPage),
  };
}
EOF
echo "wrote file:"; ls -la src/util/ordersApi.mjs'

/bin/bash -lc "echo \"=== syntax check (node --check on mjs) ===\"; node --check src/util/ordersApi.mjs && echo \"syntax OK\"; echo \"=== runtime check ===\"; node --input-type=module -e '
import { normalizeOrderList } from \"./src/util/ordersApi.mjs\";
const full = normalizeOrderList({orders:[{id:1},{id:2}], pageCount:3, totalRecords:17, itemsOnPage:5});
console.log(\"full:\", JSON.stringify(full));
const empty = normalizeOrderList({});
console.log(\"empty:\", JSON.stringify(empty));
const none = normalizeOrderList(null);
console.log(\"none:\", JSON.stringify(none));
const bad = normalizeOrderList({orders:\"x\", pageCount:\"n/a\", totalRecords:NaN, itemsOnPage:null});
console.log(\"bad:\", JSON.stringify(bad));
'"
